def generation():
    parent = ROOT / 'kg_datasets/dblp/course_v4_training_inputs_14'
    queue = parent / 'pending_generation.jsonl'
    assert c.file_sha256(parent / 'manifest.json') == 'a8a0495ead304ef943e8c1a89d344a2168b6bef5a8baab36c6970e999f8ea9db'
    assert c.file_sha256(queue) == '783e913bc0920ac77fab6977ffc175c1fabf5ed91180ecbe38acff98e533b186'
    jobs = c.read_jsonl(queue)[:200]
    assert len(jobs)==200 and [d['index'] for d in DECISIONS]==list(range(200))
    refs = {r['sampleId']:r for r in c.read_jsonl(ROOT / 'kg_datasets/dblp/course_v4_weak/references.jsonl')}
    prior = {r['reference']['sampleId'] for r in c.read_jsonl(parent / 'receipts.jsonl')}
    assert all(refs[j['sampleId']]['split']=='train' for j in jobs) and not prior.intersection(j['sampleId'] for j in jobs)
    run = ROOT / 'kg_datasets/dblp/course_v4_runs/pending_train_20261007_22'
    run.mkdir(exist_ok=False)
    c.write_jsonl(run / 'jobs.jsonl',jobs)
    c.write_json(run / 'generation_decisions.json',{'provider':'codex_session','model':'unknown_session_model','round':'generation',
        'decisions':[{k:v for k,v in d.items() if k!='index'} | {'sampleId':j['sampleId']} for d,j in zip(DECISIONS,jobs)]})
    shutil.copyfile(Path(__file__),run / 'authored_generation.py')
    dataset = ROOT / 'kg_datasets/dblp/course_v4_weak'
    compile_artifact(dataset,run / 'jobs.jsonl',run / 'generation_decisions.json',run / 'generation_compiled')
    result = import_results(dataset,run / 'generation_compiled/responses.jsonl',run / 'generation',provider='codex_session',model='unknown_session_model')
    print({'documents':result['generationReceiptDocuments'],'generationDecisionsSha256':c.file_sha256(run / 'generation_decisions.json')})


if __name__=='__main__':
    generation()
